import { useCallback, useEffect, useRef, useState } from 'react';

/**
 * useFetch(url)
 *
 * Returns { data, error, loading, refetch }.
 *
 * - Every request gets its own AbortController.
 * - A new url or a refetch() aborts the previous in-flight request.
 * - Unmounting aborts the in-flight request.
 * - Aborted requests never touch state (no error, no spurious updates).
 */
export function useFetch(url) {
  const [state, setState] = useState({ data: null, error: null, loading: true });

  // Tracks the latest committed effect so stale closures can bail out.
  const controllerRef = useRef(null);
  const mountedRef = useRef(true);

  const load = useCallback((currentUrl) => {
    // Abort whatever is still in flight before starting a new request.
    if (controllerRef.current) {
      controllerRef.current.abort();
    }

    const controller = new AbortController();
    controllerRef.current = controller;

    setState({ data: null, error: null, loading: true });

    fetch(currentUrl, { signal: controller.signal })
      .then(async (res) => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return res.json();
      })
      .then((data) => {
        if (controller.signal.aborted) return; // aborted mid-flight
        if (controllerRef.current !== controller) return;
        setState({ data, error: null, loading: false });
      })
      .catch((err) => {
        if (err?.name === 'AbortError') return; // aborted: leave state alone
        if (controller.signal.aborted) return;
        if (controllerRef.current !== controller) return;
        setState({ data: null, error: err, loading: false });
      });
  }, []);

  useEffect(() => {
    mountedRef.current = true;
    load(url);
    return () => {
      mountedRef.current = false;
      // Unmount aborts the in-flight request.
      if (controllerRef.current) {
        controllerRef.current.abort();
        controllerRef.current = null;
      }
    };
  }, [url, load]);

  const refetch = useCallback(() => {
    load(url);
  }, [url, load]);

  return { ...state, refetch };
}

export default useFetch;

