import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { renderHook, act, waitFor } from '@testing-library/react';
import { useFetch } from './use-fetch.js';

/**
 * Controllable fetch stub:
 * every call to fetch() records its AbortSignal and returns a promise we
 * can resolve/reject manually. Also hands out the controller's abort
 * handler so we can simulate the browser rejecting with AbortError.
 */
function makeFetchStub() {
  const calls = [];

  const fetchMock = vi.fn((url, init) => {
    const signal = init?.signal;
    const entry = {
      url,
      signal,
      aborted: false,
      resolveJson: (json) => {
        entry.settled = true;
        entry.resolve(new Response(JSON.stringify(json), {
          status: 200,
          headers: { 'Content-Type': 'application/json' },
        }));
      },
      rejectStatus: (status) => {
        entry.settled = true;
        entry.resolve(new Response('server error', { status }));
      },
      // Simulate what a real browser does when the signal aborts mid-flight.
      settleAborted: () => {
        entry.settled = true;
        const e = new Error('The operation was aborted.');
        e.name = 'AbortError';
        entry.reject(e);
      },
    };
    if (signal) {
      if (signal.aborted) {
        entry.aborted = true;
      } else {
        signal.addEventListener('abort', () => { entry.aborted = true; });
      }
    }
    calls.push(entry);
    return new Promise((resolve, reject) => {
      entry.resolve = resolve;
      entry.reject = reject;
    });
  });

  return { fetchMock, calls };
}

describe('useFetch', () => {
  let consoleErrorSpy;
  let stub;

  beforeEach(() => {
    stub = makeFetchStub();
    vi.stubGlobal('fetch', stub.fetchMock);
    consoleErrorSpy = vi.spyOn(console, 'error').mockImplementation(() => {});
  });

  afterEach(() => {
    vi.unstubAllGlobals();
    consoleErrorSpy.mockRestore();
  });

  function expectNoActWarnings() {
    expect(consoleErrorSpy).not.toHaveBeenCalled();
  }

  it('happy path: resolves data and clears loading', async () => {
    const { result } = renderHook(() => useFetch('/api/a'));

    expect(stub.calls).toHaveLength(1);
    expect(result.current.loading).toBe(true);
    expect(result.current.data).toBeNull();
    expect(result.current.error).toBeNull();

    await act(async () => {
      stub.calls[0].resolveJson({ hello: 'world' });
    });

    expect(result.current.loading).toBe(false);
    expect(result.current.data).toEqual({ hello: 'world' });
    expect(result.current.error).toBeNull();
    expectNoActWarnings();
  });

  it('maps a 500 response to error state', async () => {
    const { result } = renderHook(() => useFetch('/api/broken'));

    await act(async () => {
      stub.calls[0].rejectStatus(500);
    });

    expect(result.current.loading).toBe(false);
    expect(result.current.data).toBeNull();
    expect(result.current.error).toBeInstanceOf(Error);
    expect(result.current.error.message).toBe('HTTP 500');
    expectNoActWarnings();
  });

  it('aborts the in-flight request on unmount', async () => {
    const { unmount } = renderHook(() => useFetch('/api/unmount'));

    expect(stub.calls).toHaveLength(1);
    const entry = stub.calls[0];
    expect(entry.signal).toBeInstanceOf(AbortSignal);
    expect(entry.signal.aborted).toBe(false);

    unmount();

    expect(entry.signal.aborted).toBe(true);

    // The late rejection must not touch state or warn.
    await act(async () => {
      entry.settleAborted();
    });
    expectNoActWarnings();
  });

  it('aborts the previous request when the url changes', async () => {
    const { result, rerender } = renderHook(({ url }) => useFetch(url), {
      initialProps: { url: '/api/old' },
    });
    const first = stub.calls[0];

    rerender({ url: '/api/new' });

    // Old request aborted, new one started.
    expect(first.signal.aborted).toBe(true);
    expect(first.aborted).toBe(true);
    expect(stub.calls).toHaveLength(2);
    expect(stub.calls[1].url).toBe('/api/new');
    expect(stub.calls[1].signal.aborted).toBe(false);
    expect(result.current.loading).toBe(true);

    // Late response of the aborted first request is ignored.
    await act(async () => {
      first.resolveJson({ stale: true });
    });
    expect(result.current.data).toBeNull();

    // New request completes normally.
    await act(async () => {
      stub.calls[1].resolveJson({ fresh: true });
    });
    expect(result.current.data).toEqual({ fresh: true });
    expect(result.current.loading).toBe(false);
    expectNoActWarnings();
  });

  it('refetch aborts the previous in-flight request', async () => {
    const { result } = renderHook(() => useFetch('/api/refetch'));
    const first = stub.calls[0];

    act(() => {
      result.current.refetch();
    });

    expect(first.signal.aborted).toBe(true);
    expect(stub.calls).toHaveLength(2);
    expect(stub.calls[1].url).toBe('/api/refetch');
    expect(result.current.loading).toBe(true);

    // Aborting must NOT produce an error state.
    await act(async () => {
      first.settleAborted();
    });
    expect(result.current.error).toBeNull();
    expect(result.current.loading).toBe(true); // second request still pending

    await act(async () => {
      stub.calls[1].resolveJson({ n: 2 });
    });
    expect(result.current.data).toEqual({ n: 2 });
    expect(result.current.loading).toBe(false);
    expectNoActWarnings();
  });

  it('an aborted request never sets error or leaves loading stuck after refetch resolution', async () => {
    const { result } = renderHook(() => useFetch('/api/x'));

    // Unmount-triggered abort path via refetch + immediate abort simulation.
    act(() => {
      result.current.refetch();
    });
    const second = stub.calls[1];

    await act(async () => {
      second.settleAborted(); // pretend the environment rejects with AbortError
    });

    // Per spec: aborted requests must not set error state.
    expect(result.current.error).toBeNull();
    expectNoActWarnings();
  });
});

